/**
 * JSXGenerator — 把中间层 JSON 转换成可在 After Effects 中运行的 ExtendScript（§21）
 * JSX 负责：创建 Composition / Shape Layer / Text Layer / 独立预合成 / 真实关键帧 / 工程整理
 *
 * 注意：ExtendScript 仅支持 ES3 语法（无 let/const/箭头函数/模板字符串）
 */

import { AEExportJSON } from "./AEExporter";

export function generateJSX(data: AEExportJSON): string {
  const embedded = JSON.stringify(data, null, 2);

  return `// ============================================================
// DataMotion AE Project Generator
// Generated by DataMotion v${data.version}
// 在 After Effects 中：文件 > 脚本 > 运行脚本文件，选择本 .jsx
// ============================================================

var DATA = ${embedded};

// ---------------- 工具函数 ----------------

function hexToRgb(hex) {
  var h = hex.replace("#", "");
  if (h.length === 3) {
    h = h.charAt(0) + h.charAt(0) + h.charAt(1) + h.charAt(1) + h.charAt(2) + h.charAt(2);
  }
  // AE 颜色属性统一为 3 元素 [r, g, b]（含 bgColor、Fill/Stroke Color、效果颜色）
  return [
    parseInt(h.substring(0, 2), 16) / 255,
    parseInt(h.substring(2, 4), 16) / 255,
    parseInt(h.substring(4, 6), 16) / 255
  ];
}

function easeInfluence(easing) {
  // 返回 [easeInInfluence, easeOutInfluence]；linear 返回 null
  // 注意：KeyframeEase 的 influence 合法范围是 0.1 ~ 100，0 会报错
  if (easing === "easeIn") return [0.1, 60];
  if (easing === "easeOut") return [60, 0.1];
  if (easing === "easeInOut") return [60, 60];
  return null;
}

function easeArrayFor(prop, influence) {
  // 按属性维度生成 KeyframeEase 数组：1D→1 个，2D→2 个，3D→3 个
  // 注意：Scale 在 AE 脚本模型中始终是 3 维属性（即使图层是 2D）
  var dims = 1;
  if (prop.propertyValueType === PropertyValueType.ThreeD) dims = 3;
  else if (prop.propertyValueType === PropertyValueType.TwoD) dims = 2;
  var arr = [];
  for (var i = 0; i < dims; i++) arr.push(new KeyframeEase(0, influence));
  return arr;
}

function applyEase(prop, keyIndex, easing) {
  var inf = easeInfluence(easing);
  if (!inf) return;
  prop.setTemporalEaseAtKey(keyIndex, easeArrayFor(prop, inf[0]), easeArrayFor(prop, inf[1]));
}

function compCenterOffset(comp, x, y) {
  return [x - comp.width / 2, y - comp.height / 2];
}

// ---------------- 图层构建 ----------------

// 创建带圆角的矩形 Shape Layer；geometry 为合成坐标
// 注意：Shape 内容坐标系原点在合成中心，需要减去 [compW/2, compH/2]
function addRectShape(comp, name, geo, fillHex, radius) {
  var layer = comp.layers.addShape();
  layer.name = name;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.addProperty("ADBE Vector Group");
  group.name = "Rect";
  var vectors = group.property("ADBE Vectors Group");
  var rect = vectors.addProperty("ADBE Vector Shape - Rect");
  rect.property("ADBE Vector Rect Size").setValue([geo.width, geo.height]);
  rect.property("ADBE Vector Rect Position").setValue([
    geo.x + geo.width / 2 - comp.width / 2,
    geo.y + geo.height / 2 - comp.height / 2
  ]);
  if (radius && radius > 0) {
    rect.property("ADBE Vector Rect Roundness").setValue(Math.min(radius, Math.min(geo.width, geo.height) / 2));
  }
  var fill = vectors.addProperty("ADBE Vector Graphic - Fill");
  fill.property("ADBE Vector Fill Color").setValue(hexToRgb(fillHex));
  return layer;
}

// 细矩形模拟直线（网格/坐标轴）
function addLineShape(comp, name, lineGeo, strokeHex, strokeWidth) {
  var x = Math.min(lineGeo.x1, lineGeo.x2);
  var y = Math.min(lineGeo.y1, lineGeo.y2);
  var w = Math.max(Math.abs(lineGeo.x2 - lineGeo.x1), strokeWidth);
  var h = Math.max(Math.abs(lineGeo.y2 - lineGeo.y1), strokeWidth);
  return addRectShape(comp, name, { x: x, y: y, width: w, height: h }, strokeHex, 0);
}

// 创建折线路径 Shape Layer（含描边与 Trim Paths）
function addLinePathShape(comp, name, points, strokeHex, strokeWidth) {
  var layer = comp.layers.addShape();
  layer.name = name;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.addProperty("ADBE Vector Group");
  group.name = "LinePath";
  var vectors = group.property("ADBE Vectors Group");

  var shape = vectors.addProperty("ADBE Vector Shape - Group");
  var pathProp = shape.property("ADBE Vector Shape");
  var vertices = [];
  var inTangents = [];
  var outTangents = [];
  for (var i = 0; i < points.length; i++) {
    var off = compCenterOffset(comp, points[i].x, points[i].y);
    vertices.push(off);
    inTangents.push([0, 0]);
    outTangents.push([0, 0]);
  }
  var pathShape = new Shape();
  pathShape.vertices = vertices;
  pathShape.inTangents = inTangents;
  pathShape.outTangents = outTangents;
  pathShape.closed = false;
  pathProp.setValue(pathShape);

  var stroke = vectors.addProperty("ADBE Vector Graphic - Stroke");
  stroke.property("ADBE Vector Stroke Color").setValue(hexToRgb(strokeHex));
  stroke.property("ADBE Vector Stroke Width").setValue(strokeWidth);
  stroke.property("ADBE Vector Stroke Line Cap").setValue(2); // Round cap
  stroke.property("ADBE Vector Stroke Line Join").setValue(2); // Round join

  return layer;
}

// 为折线路径添加 Trim Paths 绘制动画
function addLinePathTrimAnimation(layer, startTime, duration, easing) {
  if (duration <= 0) return;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.property(1); // 第一个 Vector Group
  var vectors = group.property("ADBE Vectors Group");
  var trim = vectors.addProperty("ADBE Vector Filter - Trim");
  var endProp = trim.property("ADBE Vector Trim End");
  endProp.setValueAtTime(startTime, 0);
  endProp.setValueAtTime(startTime + duration, 100);
  // Trim Paths 关键帧用线性，避免 AE 在 Trim 属性上应用 Temporal Ease 时崩溃
}

// 创建面积填充 Shape Layer
function addAreaShape(comp, name, points, fillHex) {
  var layer = comp.layers.addShape();
  layer.name = name;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.addProperty("ADBE Vector Group");
  group.name = "Area";
  var vectors = group.property("ADBE Vectors Group");

  var shape = vectors.addProperty("ADBE Vector Shape - Group");
  var pathProp = shape.property("ADBE Vector Shape");
  var vertices = [];
  var inTangents = [];
  var outTangents = [];
  for (var i = 0; i < points.length; i++) {
    var off = compCenterOffset(comp, points[i].x, points[i].y);
    vertices.push(off);
    inTangents.push([0, 0]);
    outTangents.push([0, 0]);
  }
  var areaShape = new Shape();
  areaShape.vertices = vertices;
  areaShape.inTangents = inTangents;
  areaShape.outTangents = outTangents;
  areaShape.closed = true;
  pathProp.setValue(areaShape);

  var fill = vectors.addProperty("ADBE Vector Graphic - Fill");
  fill.property("ADBE Vector Fill Color").setValue(hexToRgb(fillHex));
  return layer;
}

// 创建数据点圆形 Shape Layer
function addPointShape(comp, name, x, y, radius, fillHex, strokeHex, strokeWidth) {
  var layer = comp.layers.addShape();
  layer.name = name;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.addProperty("ADBE Vector Group");
  group.name = "Point";
  var vectors = group.property("ADBE Vectors Group");

  var ellipse = vectors.addProperty("ADBE Vector Shape - Ellipse");
  ellipse.property("ADBE Vector Ellipse Size").setValue([radius * 2, radius * 2]);
  // 圆心在图层坐标系原点，通过 Transform 把图层原点放到合成坐标 (x, y)
  ellipse.property("ADBE Vector Ellipse Position").setValue([0, 0]);

  var fill = vectors.addProperty("ADBE Vector Graphic - Fill");
  fill.property("ADBE Vector Fill Color").setValue(hexToRgb(fillHex));

  if (strokeHex && strokeWidth > 0) {
    var stroke = vectors.addProperty("ADBE Vector Graphic - Stroke");
    stroke.property("ADBE Vector Stroke Color").setValue(hexToRgb(strokeHex));
    stroke.property("ADBE Vector Stroke Width").setValue(strokeWidth);
  }

  var transform = layer.property("ADBE Transform Group");
  transform.property("ADBE Anchor Point").setValue([0, 0]);
  transform.property("ADBE Position").setValue([x, y]);
  return layer;
}

// 为图层添加 AE 梯度渐变（Gradient Ramp）效果
// 参数顺序：渐变起点 -> 起始颜色 -> 渐变终点 -> 结束颜色 -> 渐变形状
// 参数索引依据 AE ExtendScript 标准：0001=Start of Ramp, 0002=Start Color, 0003=End of Ramp, 0004=End Color, 0005=Ramp Shape
function addGradientRampEffect(layer, startColor, endColor, startPoint, endPoint, shape) {
  var fx = addEffectSafe(layer, ["ADBE Ramp", "ADBE Gradient Ramp"]);
  var match = fx.matchName;
  fx.property(match + "-0001").setValue(startPoint); // Start of Ramp (2D)
  fx.property(match + "-0002").setValue(hexToRgb(startColor)); // Start Color (3D)
  fx.property(match + "-0003").setValue(endPoint);   // End of Ramp (2D)
  fx.property(match + "-0004").setValue(hexToRgb(endColor));   // End Color (3D)
  // 0005 Ramp Shape：1=Linear Ramp, 2=Radial Ramp
  fx.property(match + "-0005").setValue(shape === "radial" ? 2 : 1);
}

// 安全添加效果：尝试多个 match name，兼容不同 AE 版本/语言
function addEffectSafe(layer, names) {
  var lastErr = null;
  for (var i = 0; i < names.length; i++) {
    try {
      return layer.property("ADBE Effect Parade").addProperty(names[i]);
    } catch (e) {
      lastErr = e;
    }
  }
  throw lastErr || new Error("无法添加效果：" + names.join(", "));
}

// 为图层添加 AE 四色渐变（4-Color Gradient）效果
// 参数顺序：点1 -> 颜色1 -> 点2 -> 颜色2 ...
// 不依赖固定索引：按 propertyValueType 自动找出 2D 位置属性与颜色属性并依次设置
function add4ColorGradientEffect(layer, colors, points) {
  var fx = addEffectSafe(layer, ["ADBE 4Color Gradient", "ADBE 4ColorGradient", "4-Color Gradient"]);
  var pointProps = [];
  var colorProps = [];
  for (var i = 1; i <= fx.numProperties; i++) {
    try {
      var p = fx.property(i);
      if (p.propertyValueType === PropertyValueType.TwoD_SPATIAL || p.propertyValueType === PropertyValueType.TwoD) {
        pointProps.push(p);
      } else if (p.propertyValueType === PropertyValueType.COLOR) {
        colorProps.push(p);
      }
    } catch (e) {}
  }
  for (var i = 0; i < Math.min(4, pointProps.length); i++) {
    var pt = points[i] != null ? points[i] : [0, 0];
    pointProps[i].setValue(pt);
  }
  for (var i = 0; i < Math.min(4, colorProps.length); i++) {
    var c = colors[i] != null ? colors[i] : (colors[0] != null ? colors[0] : "#000000");
    colorProps[i].setValue(hexToRgb(c));
  }
}

// 根据渐变配置自动添加对应 AE 效果
function addGradientEffect(layer, gradient) {
  if (!gradient || gradient.mode === "none") return;
  if (gradient.mode === "ramp" && gradient.ramp) {
    addGradientRampEffect(
      layer,
      gradient.ramp.startColor,
      gradient.ramp.endColor,
      gradient.ramp.startPoint,
      gradient.ramp.endPoint,
      gradient.ramp.shape || "linear"
    );
  } else if (gradient.mode === "4color" && gradient.fourColor) {
    add4ColorGradientEffect(layer, gradient.fourColor.colors, gradient.fourColor.points);
  }
}

// 创建饼图扇形 Shape Layer（实心或环形）
// 圆心置于图层坐标系原点，通过 Transform 把图层原点放到合成坐标 (cx, cy)
function addPieSliceShape(comp, name, geo, fillHex) {
  var layer = comp.layers.addShape();
  layer.name = name;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.addProperty("ADBE Vector Group");
  group.name = "Slice";
  var vectors = group.property("ADBE Vectors Group");

  var shape = vectors.addProperty("ADBE Vector Shape - Group");
  var pathProp = shape.property("ADBE Vector Shape");

  var vertices = [];
  var inTangents = [];
  var outTangents = [];

  var toRad = function(deg) { return deg * Math.PI / 180; };
  var arcPoints = function(r, startDeg, endDeg, segments) {
    var pts = [];
    var span = endDeg - startDeg;
    if (span <= 0) span += 360;
    for (var i = 0; i <= segments; i++) {
      var deg = startDeg + span * i / segments;
      var rad = toRad(deg);
      pts.push([r * Math.cos(rad), r * Math.sin(rad)]);
    }
    return pts;
  };

  var outer = arcPoints(geo.radius, geo.startAngle, geo.endAngle, 24);
  if (geo.innerRadius > 0) {
    var inner = arcPoints(geo.innerRadius, geo.endAngle, geo.startAngle, 24);
    for (var i = 0; i < outer.length; i++) {
      vertices.push(outer[i]);
      inTangents.push([0, 0]);
      outTangents.push([0, 0]);
    }
    for (var i = 0; i < inner.length; i++) {
      vertices.push(inner[i]);
      inTangents.push([0, 0]);
      outTangents.push([0, 0]);
    }
  } else {
    // 实心扇形：圆心 + 外弧 + 回到圆心
    vertices.push([0, 0]);
    inTangents.push([0, 0]);
    outTangents.push([0, 0]);
    for (var i = 0; i < outer.length; i++) {
      vertices.push(outer[i]);
      inTangents.push([0, 0]);
      outTangents.push([0, 0]);
    }
    vertices.push([0, 0]);
    inTangents.push([0, 0]);
    outTangents.push([0, 0]);
  }

  var sliceShape = new Shape();
  sliceShape.vertices = vertices;
  sliceShape.inTangents = inTangents;
  sliceShape.outTangents = outTangents;
  sliceShape.closed = true;
  pathProp.setValue(sliceShape);

  var fill = vectors.addProperty("ADBE Vector Graphic - Fill");
  fill.property("ADBE Vector Fill Color").setValue(hexToRgb(fillHex));

  var transform = layer.property("ADBE Transform Group");
  transform.property("ADBE Anchor Point").setValue([0, 0]);
  transform.property("ADBE Position").setValue([geo.cx, geo.cy]);
  return layer;
}

// 为饼图扇形添加 Trim Paths 展开动画（End 0→100）
function addPieSliceExpandAnimation(layer, startTime, duration, easing) {
  if (duration <= 0) return;
  var root = layer.property("ADBE Root Vectors Group");
  var group = root.property(1); // 第一个 Vector Group
  var vectors = group.property("ADBE Vectors Group");
  var trim = vectors.addProperty("ADBE Vector Filter - Trim");
  // Trim Paths 使用线性关键帧，避免 Temporal Ease 在部分 AE 版本上不稳定
  var endProp = trim.property("ADBE Vector Trim End");
  endProp.setValueAtTime(startTime, 0);
  endProp.setValueAtTime(startTime + duration, 100);
}

// 生长动画：调整锚点到生长基线后用 Scale 关键帧（§25 底部固定）
// 严格保持旧版本行为：只处理 bar 的 y/x 轴向生长
function addGrowAnimation(layer, comp, geo, axis, startTime, duration, easing) {
  var transform = layer.property("ADBE Transform Group");
  var anchor = transform.property("ADBE Anchor Point");
  var position = transform.property("ADBE Position");
  var scale = transform.property("ADBE Scale");

  // 图层坐标 = 合成坐标 - 合成中心；锚点设为生长基线（图层坐标系）
  var cx = comp.width / 2;
  var cy = comp.height / 2;
  var newAnchor;
  if (axis === "y") {
    newAnchor = [geo.x + geo.width / 2 - cx, geo.y + geo.height - cy]; // 底部中心
  } else {
    newAnchor = [geo.x - cx, geo.y + geo.height / 2 - cy]; // 左侧中心
  }
  anchor.setValue(newAnchor);
  // 保持内容位置不变：position = 合成中心 + 锚点
  position.setValue([cx + newAnchor[0], cy + newAnchor[1]]);

  var fromScale = axis === "y" ? [100, 0.01] : [0.01, 100];
  scale.setValueAtTime(startTime, fromScale);
  scale.setValueAtTime(startTime + duration, [100, 100]);
  applyEase(scale, 1, easing);
  applyEase(scale, 2, easing);
}

// point 生长动画：图层原点已在圆心，从中心整体缩放
function addPointGrowAnimation(layer, startTime, duration, easing) {
  var scale = layer.property("ADBE Transform Group").property("ADBE Scale");
  scale.setValueAtTime(startTime, [0.01, 0.01]);
  scale.setValueAtTime(startTime + duration, [100, 100]);
  applyEase(scale, 1, easing);
  applyEase(scale, 2, easing);
}

function addFadeAnimation(layer, startTime, duration, easing) {
  var opacity = layer.property("ADBE Transform Group").property("ADBE Opacity");
  opacity.setValueAtTime(startTime, 0);
  opacity.setValueAtTime(startTime + duration, 100);
  applyEase(opacity, 1, easing);
  applyEase(opacity, 2, easing);
}

function addMoveAnimation(layer, startTime, duration, easing) {
  var position = layer.property("ADBE Transform Group").property("ADBE Position");
  var finalPos = position.value;
  position.setValueAtTime(startTime, [finalPos[0], finalPos[1] + 30]);
  position.setValueAtTime(startTime + duration, finalPos);
  applyEase(position, 1, easing);
  applyEase(position, 2, easing);
}

function justificationFor(anchor) {
  if (anchor === "middle") return ParagraphJustification.CENTER_JUSTIFY;
  if (anchor === "end") return ParagraphJustification.RIGHT_JUSTIFY;
  return ParagraphJustification.LEFT_JUSTIFY;
}

function baselineOffset(baseline, fontSize) {
  if (baseline === "top") return fontSize * 0.8;
  if (baseline === "middle") return fontSize * 0.35;
  return 0;
}

// 创建文字图层
function addTextLayer(comp, el) {
  var layer = comp.layers.addText(el.text || "");
  layer.name = el.type === "value" ? "Value" : "Label";
  var textProp = layer.property("ADBE Text Properties").property("ADBE Text Document");
  var td = textProp.value;
  td.fontSize = el.style.fontSize;
  td.fillColor = hexToRgb(el.style.fill);
  td.justification = justificationFor(el.geometry.anchor);
  try { td.font = el.style.fontFamily; } catch (e) {}
  textProp.setValue(td);

  var position = layer.property("ADBE Transform Group").property("ADBE Position");
  position.setValue([el.geometry.x, el.geometry.y + baselineOffset(el.geometry.baseline, el.style.fontSize)]);
  return layer;
}

// 数值变化动画（滑块 + 表达式方案）：
// 1. 为 Value 图层添加 Slider Control，自定义 ASCII 名字 "ValueCtrl"（表达式查询用，跨语言稳定）
// 2. 滑块打两个关键帧：0 → sliderEnd（已放大 100 倍），并应用缓动
// 3. 源文本绑定表达式：effect("ValueCtrl")(1) / 100 还原数值并格式化
function addValueSlider(layer, valueEl, easing) {
  var anim = valueEl.animation;
  if (!anim || !anim.expression || anim.sliderEnd === undefined) return;

  var fx = layer.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
  fx.name = "ValueCtrl"; // 必须与表达式中的 effect("ValueCtrl") 一致
  var slider = fx.property("ADBE Slider Control-0001");
  // 注意：slider.minValue / maxValue 在脚本中为只读（默认范围 0~100），
  // 无法设置；关键帧值可超出该范围正常工作（表达式读到的仍是实际值），
  // 只是手动拖动滑块时被限制在 0~100。
  slider.setValueAtTime(anim.startTime, 0);
  slider.setValueAtTime(anim.startTime + anim.duration, anim.sliderEnd);
  applyEase(slider, 1, easing);
  applyEase(slider, 2, easing);

  var textProp = layer.property("ADBE Text Properties").property("ADBE Text Document");
  textProp.expression = anim.expression;
}

// ---------------- 主流程 ----------------

function findElements(data, type) {
  var out = [];
  for (var i = 0; i < data.elements.length; i++) {
    if (data.elements[i].type === type) out.push(data.elements[i]);
  }
  return out;
}

function findByBarId(data, barId, type) {
  for (var i = 0; i < data.elements.length; i++) {
    var el = data.elements[i];
    if (el.barId === barId && el.type === type) return el;
  }
  return null;
}

function build() {
  var comp = DATA.composition;
  var easing = DATA.animation.easing;

  app.beginUndoGroup("DataMotion Generate");

  // 1. 工程目录结构（§22）
  var rootFolder = app.project.items.addFolder(DATA.name);
  var folderMain = app.project.items.addFolder("01_MAIN");
  var folderChart = app.project.items.addFolder("02_CHART");
  var folderControl = app.project.items.addFolder("04_CONTROL");
  var folderAssets = app.project.items.addFolder("05_ASSETS");
  folderMain.parentFolder = rootFolder;
  folderChart.parentFolder = rootFolder;
  folderControl.parentFolder = rootFolder;
  folderAssets.parentFolder = rootFolder;

  // 2. Main Composition
  var mainComp = app.project.items.addComp(
    "COMP_Main", comp.width, comp.height, 1, comp.duration, comp.fps
  );
  mainComp.parentFolder = folderMain;
  mainComp.bgColor = hexToRgb(comp.background);

  // 3. 全局控制 Null（图层无法放入文件夹，04_CONTROL 预留给后续控制器资产）
  var ctrl = mainComp.layers.addNull();
  ctrl.name = "CTRL_Global";

  // 4. 网格线、坐标轴与网格数值标签（直接在 Main 中）
  var grids = findElements(DATA, "grid");
  for (var g = 0; g < grids.length; g++) {
    addLineShape(mainComp, "Grid_" + (g + 1), grids[g].geometry, grids[g].style.stroke, grids[g].style.strokeWidth);
  }
  var axes = findElements(DATA, "axis");
  for (var a = 0; a < axes.length; a++) {
    addLineShape(mainComp, "Axis", axes[a].geometry, axes[a].style.stroke, axes[a].style.strokeWidth);
  }
  var gridLabels = findElements(DATA, "grid-label");
  for (var gl = 0; gl < gridLabels.length; gl++) {
    addTextLayer(mainComp, gridLabels[gl]);
  }

  // 5. 折线图：面积填充与折线路径置于主合成
  var areas = findElements(DATA, "line-area");
  for (var ar = 0; ar < areas.length; ar++) {
    var area = areas[ar];
    var areaLayer = addAreaShape(mainComp, "LineArea", area.geometry.points, area.style.fill);
    if (area.style.gradient && area.style.gradient.mode !== "none") {
      addGradientEffect(areaLayer, area.style.gradient);
    }
  }
  var linePaths = findElements(DATA, "line-path");
  for (var lp = 0; lp < linePaths.length; lp++) {
    var pathEl = linePaths[lp];
    var pathLayer = addLinePathShape(mainComp, "LinePath", pathEl.geometry.points, pathEl.style.stroke, pathEl.style.strokeWidth);
    if (pathEl.animation && pathEl.animation.growAxis) {
      addLinePathTrimAnimation(pathLayer, pathEl.animation.startTime, pathEl.animation.duration, pathEl.animation.easing || easing);
    }
    if (pathEl.style.gradient && pathEl.style.gradient.mode !== "none") {
      addGradientEffect(pathLayer, pathEl.style.gradient);
    }
  }

  // 6. 每个主元素独立预合成（§23）：柱状图的 bar / 折线图的 line-point / 饼图的 pie-slice
  var primaries = [];
  for (var i = 0; i < DATA.elements.length; i++) {
    var el = DATA.elements[i];
    if (el.type === "bar" || el.type === "line-point" || el.type === "pie-slice") primaries.push(el);
  }
  for (var i = 0; i < primaries.length; i++) {
    var primary = primaries[i];
    var preName = "PRECOMP_" + primary.id.replace("bar-", "Bar_").replace("line-point-", "Point_").replace("pie-slice-", "Slice_");
    var pre = app.project.items.addComp(preName, comp.width, comp.height, 1, comp.duration, comp.fps);
    pre.parentFolder = folderChart;
    pre.bgColor = hexToRgb(comp.background);

    var anim = primary.animation;
    var startTime = anim ? anim.startTime : 0;
    var duration = anim ? anim.duration : 1;

    if (primary.type === "bar") {
      // Bar Body
      var barLayer = addRectShape(pre, "Bar Body", primary.geometry, primary.style.fill, primary.geometry.radius || 0);
      if (anim && anim.growAxis) {
        addGrowAnimation(barLayer, pre, primary.geometry, anim.growAxis, startTime, duration, anim.easing || easing);
      }
      if (primary.style.gradient && primary.style.gradient.mode !== "none") {
        addGradientEffect(barLayer, primary.style.gradient);
      }
    } else if (primary.type === "line-point") {
      // Point
      var pointLayer = addPointShape(
        pre, "Point",
        primary.geometry.x, primary.geometry.y, primary.geometry.radius,
        primary.style.fill, primary.style.stroke, primary.style.strokeWidth || 0
      );
      if (anim && anim.growAxis) {
        addPointGrowAnimation(pointLayer, startTime, duration, anim.easing || easing);
      }
    } else if (primary.type === "pie-slice") {
      // Pie Slice
      var sliceLayer = addPieSliceShape(pre, "Slice", primary.geometry, primary.style.fill);
      if (anim) {
        var pieEasing = anim.easing || easing;
        var pieAnimType = anim.pieAnimationType || "expand";
        if (pieAnimType === "expand") {
          addPieSliceExpandAnimation(sliceLayer, startTime, duration, pieEasing);
        } else if (anim.growAxis) {
          addPointGrowAnimation(sliceLayer, startTime, duration, pieEasing);
        }
      }
    }

    // Label（独立图层）
    var labelEl = findByBarId(DATA, primary.id, "label");
    if (labelEl) {
      var labelLayer = addTextLayer(pre, labelEl);
      labelLayer.name = "Label";
      if (labelEl.animation) {
        var labelEasing = labelEl.animation.easing || easing;
        if (labelEl.animation.fade) addFadeAnimation(labelLayer, labelEl.animation.startTime, labelEl.animation.duration, labelEasing);
        if (labelEl.animation.move) addMoveAnimation(labelLayer, labelEl.animation.startTime, labelEl.animation.duration, labelEasing);
      }
    }

    // Value（独立图层 + 滑块/表达式数值动画）
    var valueEl = findByBarId(DATA, primary.id, "value");
    if (valueEl) {
      var valueLayer = addTextLayer(pre, valueEl);
      valueLayer.name = "Value";
      if (valueEl.animation) {
        var valueEasing = valueEl.animation.easing || easing;
        addValueSlider(valueLayer, valueEl, valueEasing);
        if (valueEl.animation.fade) addFadeAnimation(valueLayer, valueEl.animation.startTime, valueEl.animation.duration, valueEasing);
        if (valueEl.animation.move) addMoveAnimation(valueLayer, valueEl.animation.startTime, valueEl.animation.duration, valueEasing);
      }
    }

    // 预合成放回 Main
    mainComp.layers.add(pre);
  }

  // 7. 打开 Main 并保存
  mainComp.openInViewer();

  app.endUndoGroup();

  var saveFile = File.saveDialog("保存 DataMotion AE 工程", "*.aep");
  if (saveFile) {
    app.project.save(saveFile);
    alert("DataMotion 工程已生成并保存：\\n" + saveFile.fsName);
  } else {
    alert("DataMotion 工程已生成（尚未保存）。\\n可在 AE 中继续编辑后手动保存。");
  }
}

build();
`;
}
